import sys
import click

REAL_OUT, REAL_ERR = sys.stdout, sys.stderr

def log(msg):
    REAL_OUT.write(msg + "\n")
    REAL_OUT.flush()

def run(name, fn):
    try:
        fn()
        log(f"OK   {name}")
    except Exception as e:
        log(f"FAIL {name}: {type(e).__name__}: {e}")

def pb():
    with click.progressbar(range(3), label="working"):
        pass

for which in ("stdout", "stderr"):
    setattr(sys, which, None)
    run(f"echo(str) {which}=None", lambda: click.echo("x"))
    run(f"echo(bytes) {which}=None", lambda: click.echo(b"x"))
    run(f"echo() {which}=None", lambda: click.echo())
    run(f"echo(err=True) {which}=None", lambda: click.echo("x", err=True))
    run(f"progressbar {which}=None", pb)
    run(f"echo_via_pager {which}=None", lambda: click.echo_via_pager("hello"))
    setattr(sys, which, REAL_OUT if which == "stdout" else REAL_ERR)
